-- Resources: portal-basics procedures (docs/resources-design.md slice 5 --
-- "backfill guides for each tool" -- starting with basic portal usage,
-- which has no tool_id to hang a guide off of, so it's three procedures
-- under a new "Using the portal" area instead. Content only, no schema
-- change -- rc_articles/rc_article_versions already support this shape.
-- Upserts on slug, like the resources seed migration; guarded by
-- edited_since_release so a later staff edit is never silently overwritten.

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, area, owner_role, sort_order, source, version_note)
values (
  'portal-signing-in-and-requesting-access', 'procedure'::public.rc_kind, 'Signing in and requesting access', 'The one-time email link, and what happens if you don''t have an account yet.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The portal uses passwordless sign-in: there''s no account password to remember, and no self-service account creation. You always start from the sign-in page."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Sign in"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to the sign-in page and enter your work or university email."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Send sign-in link","marks":[{"type":"bold"}]},{"type":"text","text":". Check your email for a one-time link — it''s valid for 15 minutes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select the link in the email — you''re signed in, no password to enter."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Don''t have an account yet?"}]},{"type":"paragraph","content":[{"type":"text","text":"If you enter an email the portal doesn''t recognize, it offers a "},{"type":"text","text":"Request access","marks":[{"type":"bold"}]},{"type":"text","text":" button instead of a sign-in error."}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in your full name and email."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Optionally describe what you need access to — this helps whoever reviews the request."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Send request","marks":[{"type":"bold"}]},{"type":"text","text":". A WUWF Tools administrator reviews it, and you''ll get an email once it''s decided."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A sign-in link expires after 15 minutes. If it''s lapsed, just request a new one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Being signed in and having access to a specific tool are different things — see "},{"type":"text","text":"Your dashboard: tools you can open","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If a link that used to work suddenly doesn''t, your account may have been disabled. Contact an administrator."}]}]}]}]}'::jsonb,
  '{staff,students,partners}'::public.rc_audience[], 'Using the portal', null, 10,
  'editor'::public.rc_source, 'Initial version'
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  area = excluded.area, owner_role = excluded.owner_role,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, area, owner_role, sort_order, source, version_note)
values (
  'portal-dashboard-and-tool-access', 'procedure'::public.rc_kind, 'Your dashboard: tools you can open', 'What an open, restricted, or coming-soon tool card means, and how access is granted.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Your dashboard lists every tool as a card. What a card looks like tells you whether you can open it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Reading a card"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open","marks":[{"type":"bold"}]},{"type":"text","text":" — a blue-bordered card with an "},{"type":"text","text":"Open","marks":[{"type":"bold"}]},{"type":"text","text":" button. You already have access; select it to go there."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Restricted","marks":[{"type":"bold"}]},{"type":"text","text":" — a grayed-out card reading “Contact an administrator to request access.” The tool exists, but nobody has granted you access to it yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Coming soon","marks":[{"type":"bold"}]},{"type":"text","text":" — a dashed-border card. The tool is being built and isn''t usable yet."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How access is decided"}]},{"type":"paragraph","content":[{"type":"text","text":"Every tool is set up one of two ways:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Open to any active staff member by default — Roadmap and Resources work this way, so everyone sees an "},{"type":"text","text":"Open","marks":[{"type":"bold"}]},{"type":"text","text":" card for them with no request needed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Invite-only — most tools (Sourcework, Log, Underwriting & Traffic, Audience Listening, and the rest) require an administrator to grant you access individually."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A few tools have a further, elevated role on top of plain access — a Log “producer,” a Roadmap “curator,” an Underwriting “manager.” That''s separate from being let into the tool at all, and it''s also set by an administrator."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A tool that isn''t on your dashboard at all may not be built yet. Check "},{"type":"text","text":"Roadmap","marks":[{"type":"bold"}]},{"type":"text","text":" to see what''s planned, or ask an administrator."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Losing access to a tool never deletes anything you created in it — it just stops you opening it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If you think you should have access to something and don''t, the restricted card''s own message is the fastest path: contact an administrator directly."}]}]}]}]}'::jsonb,
  '{staff,students,partners}'::public.rc_audience[], 'Using the portal', null, 20,
  'editor'::public.rc_source, 'Initial version'
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  area = excluded.area, owner_role = excluded.owner_role,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

insert into public.rc_articles
  (slug, kind, title, summary, body, audience, area, owner_role, sort_order, source, version_note)
values (
  'portal-getting-help', 'procedure'::public.rc_kind, 'Getting help while you work', 'The in-tool Help panel, and the Resources area''s procedures, guides, and what''s new.',
  '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two things point you to documentation while you work: the Help panel on a tool''s own screens, and the Resources area itself."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Help panel"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On any screen inside a tool, select "},{"type":"text","text":"Help","marks":[{"type":"bold"}]},{"type":"text","text":" in the header to open a panel down the right side of the screen."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"“For this screen” lists the guides written for exactly the screen you''re on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"“Changed recently” shows that tool''s latest release notes, so you can see what''s different since you last used it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The search box in the panel searches every guide for that tool."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The Help panel and the in-portal assistant share the same space on the right — opening one closes the other."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The Resources area"}]},{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Resources","marks":[{"type":"bold"}]},{"type":"text","text":" in the top navigation for everything at once: station procedures, one set of guides per tool, and "},{"type":"text","text":"What''s new","marks":[{"type":"bold"}]},{"type":"text","text":" — every user-visible change, newest first. The search box on the Resources home page searches across all of it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Guides describe screens as they exist today. If a guide looks out of date, it may be flagged for an editor to review — that''s not something you need to act on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anyone with portal access can read Resources. Only designated editors (or an administrator) can write or change it."}]}]}]}]}'::jsonb,
  '{staff,students,partners}'::public.rc_audience[], 'Using the portal', null, 30,
  'editor'::public.rc_source, 'Initial version'
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, body = excluded.body,
  area = excluded.area, owner_role = excluded.owner_role,
  sort_order = excluded.sort_order, source = excluded.source,
  version_note = excluded.version_note
where not public.rc_articles.edited_since_release;

